cd /work; psql -q <<'EOF'
insert into orders select max(order_id)+1,(select min(customer_id) from customers),now(),'COMPLETED',0 from orders;
-- first line (lowest item id) category A, second line category B
insert into order_items select (select max(order_item_id) from order_items)+1,(select max(order_id) from orders),
 (select product_id from products where category=(select min(category) from products) limit 1),2,10;
insert into order_items select (select max(order_item_id) from order_items)+1,(select max(order_id) from orders),
 (select product_id from products where category=(select max(category) from products) limit 1),3,7;
EOF
psql -v ON_ERROR_STOP=1 -q -f etl.sql
psql -c "select min(category),max(category) from products" -c "select * from etl_run_log order by run_id desc limit 1" -c "select * from dash_revenue_by_category where month='2026-10'" -c "select * from dash_revenue_by_country where month='2026-10' and country=(select country from customers order by customer_id limit 1)"

